//MESH_BEGIN
u: 0, pi/2, 40
v: -1, 1, 40
//MESH_END

// Brieskorn-Pham surface:  z1^a + z2^b = 1,  with z1,z2 complex.
// Generalizes the Calabi-Yau section: there the two exponents were EQUAL (the
// Fermat quintic, a = b = n), here they are INDEPENDENT and driven by two
// separate sliders. With a != b the figure loses the swap symmetry between
// the two complex coordinates and changes genus: it is a topologically
// different family, not a deformation of the same shape.
//
// For each pair of roots (k1 of order a, k2 of order b) there is a patch:
//   z1 = e^(2 pi i k1/a) * (cos w)^(2/a)
//   z2 = e^(2 pi i k2/b) * (sin w)^(2/b)     with w = u + i v
//
// TRUE 4D SURFACE: Im(z2) comes out as the w component of the vec4, so the 4D
// projection and rotations stay with the interface (as in the "Calabi-Yau"
// preset, not in the "3D" variant that mixes the fourth coordinate inside the script).
//
// STATIC GRIDS: they are read at Run, so we declare the maximum 49 = 7x7 and
// discard the extra ones in the cutout. The indices are NOT in a fixed base 7:
// they are computed on the live grid (k1 = mesh % a, k2 = mesh / a), so the
// surviving patches are the first a*b and the mesh counter never offers numbers
// that point to discarded patches.

A := int(2,7);          // esponente di z1: slider a scatti interi
B := int(2,7);          // esponente di z2: slider a scatti interi
MESH_VISIBLE := A*B;    // quante griglie sopravvivono al cutout

// clamp: protects the geometry if the slider leaves the declared domain.
// It must be replicated IDENTICAL in the CUTOUT block, or the live patches do not match.
float na = clamp(floor(A + 0.5), 2.0, 7.0);
float nb = clamp(floor(B + 0.5), 2.0, 7.0);

// COMPACT NUMBERING: the indices are computed on the LIVE grid (na x nb),
// not on the fixed base 7. This way the surviving patches are the FIRST na*nb in
// mesh order, and the interface counter (which maps number -> mesh
// as value()-1) always points to a patch that is actually visible.
// With the old base 7 the live ones were 0,1,2, 7,8,9, 14... and from the fourth
// number on the selector fell on patches discarded by the cutout: inert sliders.
// The (k1,k2) PAIRS drawn are the same as before: what changes is the index that
// carries them, not the figure.
float k1 = mod(float(mesh), na);
float k2 = floor(float(mesh) / na);

float pa = 2.0 / na;
float pb = 2.0 / nb;

// w = u + i v;  cos(w) e sin(w) complessi
vec2 cw = vec2( cos(u) * cosh(v), -sin(u) * sinh(v));
vec2 sw = vec2( sin(u) * cosh(v),  cos(u) * sinh(v));

// Complex power in polar form. On the declared domain Re(cos w) and
// Re(sin w) stay POSITIVE: the argument lies in (-pi/2, pi/2), far from the
// atan jump, so there is no branch cut and no seams between patches.
float rc = safePow(length(cw), pa);
float tc = pa * atan(cw.y, cw.x);
float rs = safePow(length(sw), pb);
float ts = pb * atan(sw.y, sw.x);

// Radici dell'unita': e^(2 pi i k1/a) e e^(2 pi i k2/b) -- ordini DIVERSI.
float t1 = 2.0 * pi * k1 / na;
float t2 = 2.0 * pi * k2 / nb;

vec2 z1 = rc * vec2(cos(tc + t1), sin(tc + t1));
vec2 z2 = rs * vec2(cos(ts + t2), sin(ts + t2));

// (Re z1, Re z2, Im z1) in R^3 + Im z2 as the fourth coordinate.
// Slider C scales the fourth dimension: at C=0 the figure collapses into R^3
// (useful to compare it with the 3D view), at C=1 it is the full 4D surface.
return vec4(z1.x, z2.x, z1.y, C * z2.y);

//CUTOUT_BEGIN
// Discard the TAIL: with the compact numbering of the body the live patches are
// the first ca*cb, so a comparison on the index is enough. The clamp stays
// replicated identical to the body (na/nb), or the live patches do not match.
float ca = clamp(floor(A + 0.5), 2.0, 7.0);
float cb = clamp(floor(B + 0.5), 2.0, 7.0);
return float(mesh) > ca * cb - 0.5;
//CUTOUT_END
